from __future__ import annotations

from sigforge.models import SigSpec, validate_spec


def generate_python_scanner(spec: SigSpec) -> str:
    validate_spec(spec)

    lines: list[str] = [
        "# Auto-generated by sigforge. Zero external dependencies.",
        "from __future__ import annotations",
        "",
        "import struct",
        "from typing import Sequence",
        "",
        "PATTERNS: dict[str, dict[str, object]] = {",
    ]

    for entry in spec.signatures:
        toks = entry.tokens()
        toks_repr = repr(toks)
        min_len = max(len(toks), entry.byte_length)
        rip_repr = repr(entry.rip_capture.to_dict()) if entry.rip_capture else "None"
        lines.append(
            f"    {entry.name!r}: {{"
            f"'pattern': {entry.pattern!r}, "
            f"'tokens': {toks_repr}, "
            f"'min_len': {min_len}, "
            f"'rip_capture': {rip_repr}"
            "},"
        )

    lines.extend(
        [
            "}",
            "",
            "",
            "def _scan_all(",
            "    buf: bytes, tokens: Sequence[int | None], max_hits: int = 0, min_len: int = 0",
            ") -> list[int]:",
            "    pat_len = len(tokens)",
            "    req_len = max(pat_len, min_len)",
            "    if pat_len == 0 or len(buf) < req_len:",
            "        return []",
            "    first_byte = tokens[0]",
            "    if first_byte is None:",
            "        return []",
            "    last_idx = 0",
            "    for i in range(pat_len - 1, -1, -1):",
            "        if tokens[i] is not None:",
            "            last_idx = i",
            "            break",
            "    last_byte = tokens[last_idx]",
            "    checks = [(i, b) for i, b in enumerate(tokens) if b is not None and i not in (0, last_idx)]",
            "    hits: list[int] = []",
            "    limit = len(buf) - req_len",
            "    pos = 0",
            "    while pos <= limit:",
            "        hit = buf.find(first_byte, pos, limit + 1)",
            "        if hit == -1:",
            "            break",
            "        if buf[hit + last_idx] == last_byte:",
            "            matched = True",
            "            for idx, val in checks:",
            "                if buf[hit + idx] != val:",
            "                    matched = False",
            "                    break",
            "            if matched:",
            "                hits.append(hit)",
            "                if max_hits > 0 and len(hits) >= max_hits:",
            "                    break",
            "        pos = hit + 1",
            "    return hits",
            "",
            "",
            "def _scan_first(buf: bytes, tokens: Sequence[int | None], min_len: int = 0) -> int | None:",
            "    hits = _scan_all(buf, tokens, max_hits=1, min_len=min_len)",
            "    return hits[0] if hits else None",
        ]
    )

    for entry in spec.signatures:
        lines.extend(
            [
                "",
                "",
                f"def scan_first_{entry.name}(buf: bytes) -> int | None:",
                f"    meta = PATTERNS[{entry.name!r}]",
                "    tokens = meta['tokens']",
                "    min_len = meta['min_len']",
                "    assert isinstance(tokens, list) and isinstance(min_len, int)",
                "    return _scan_first(buf, tokens, min_len=min_len)",
                "",
                "",
                f"def scan_all_{entry.name}(buf: bytes, max_hits: int = 0) -> list[int]:",
                f"    meta = PATTERNS[{entry.name!r}]",
                "    tokens = meta['tokens']",
                "    min_len = meta['min_len']",
                "    assert isinstance(tokens, list) and isinstance(min_len, int)",
                "    return _scan_all(buf, tokens, max_hits=max_hits, min_len=min_len)",
            ]
        )
        if entry.rip_capture is not None:
            rc = entry.rip_capture
            lines.extend(
                [
                    "",
                    "",
                    f"def resolve_{entry.name}_rip_target(buf: bytes, base_rva: int = 0) -> int | None:",
                    f"    hit = scan_first_{entry.name}(buf)",
                    "    if hit is None:",
                    "        return None",
                    f"    if hit + {rc.next_ip_offset} > len(buf):",
                    "        return None",
                    f"    disp = struct.unpack_from('<i', buf, hit + {rc.disp_offset})[0]",
                    f"    return (base_rva + hit + {rc.next_ip_offset} + disp) & 0xFFFFFFFFFFFFFFFF",
                ]
            )

    return "\n".join(lines) + "\n"
